// Times the C that Oak's backend emits for the UTF-8 protocol
// (utf8_protocol.oak -> utf8_protocol.c, regenerated by
// OAK_UPDATE_BENCH=1 go test ./compiler -run TestEmitStateMachineBenchmarkSource)
// over the same 64 MB of random valid UTF-8 that lowerings.c feeds its
// hand-written variants. The Oak program's own main is renamed away.
//
// Build: cc -std=c11 -O2 -o run_utf8 run_utf8.c -lm ; run: ./run_utf8
#define main oak_program_main
#include "utf8_protocol.c"
#undef main
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static double now_ns(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec * 1e9 + (double)ts.tv_nsec;
}
static u64 rng_state = 0x9E3779B97F4A7C15ull;
static inline u32 rng(void) {
    u64 x = rng_state; x ^= x >> 12; x ^= x << 25; x ^= x >> 27; rng_state = x;
    return (u32)((x * 0x2545F4914F6CDD1Dull) >> 32);
}

int main(void) {
    const u32 n = 64u << 20;
    u8 *buf = malloc(n + 4);
    u32 i = 0;
    while (i + 4 <= n) {
        u32 r = rng(); u32 kind = r % 10; u32 cp;
        if (kind < 6) cp = 32 + (r >> 8) % 95;
        else if (kind < 8) cp = 0x80 + (r >> 8) % (0x800 - 0x80);
        else if (kind < 9) { cp = 0x800 + (r >> 8) % (0xFFFF - 0x800); if (cp >= 0xD800 && cp <= 0xDFFF) cp = 0x4E00; }
        else cp = 0x10000 + (r >> 8) % (0x10FFFF - 0x10000);
        if (cp < 0x80) buf[i++] = (u8)cp;
        else if (cp < 0x800) { buf[i++] = (u8)(0xC0 | (cp >> 6)); buf[i++] = (u8)(0x80 | (cp & 63)); }
        else if (cp < 0x10000) { buf[i++] = (u8)(0xE0 | (cp >> 12)); buf[i++] = (u8)(0x80 | ((cp >> 6) & 63)); buf[i++] = (u8)(0x80 | (cp & 63)); }
        else { buf[i++] = (u8)(0xF0 | (cp >> 18)); buf[i++] = (u8)(0x80 | ((cp >> 12) & 63)); buf[i++] = (u8)(0x80 | ((cp >> 6) & 63)); buf[i++] = (u8)(0x80 | (cp & 63)); }
    }
    while (i < n) buf[i++] = 'a';

    oak_view_u8 view; view.base = buf; view.len = n;
    double best = 1e30; u32 final = 0;
    for (int rep = 0; rep < 5; rep++) {
        double t0 = now_ns();
        oak_Utf8State s = oak_utf8_run(oak_utf8_initial(), view);
        double t = now_ns() - t0;
        if (t < best) best = t;
        final = s.tag;
    }
    printf("Oak utf8_run (shift DFA emitted by the backend), %u bytes\n", n);
    printf("   %6.2f ns/byte  (%.2f GB/s)  final tag %u (%s)\n", best / n, n / best, final, final == oak_Utf8State_tag_Accept ? "Accept" : "other");
    free(buf);
    return 0;
}
